#!/bin/bash
#SBATCH --job-name=era5-dl-4yr
#SBATCH --output=/zooper2/shaurya.sen/work/balloon-env-dev/runs/%x-%j.out
#SBATCH --cpus-per-task=2
#SBATCH --mem=8G
#SBATCH --time=7-00:00:00
#SBATCH --signal=B:TERM@120
#
# Download + ingest ERA5 training years 2020-2022 — CPU-only sbatch job on the Kahan
# COMPUTE node (no GPU requested). It cannot run on the login node: kahanctrl's CPU
# predates x86-64-v2, so modern numpy wheels refuse to import there (RuntimeError at
# import; stricter than the old "no AVX -> no JAX" note). The compute node has internet
# (verified) and runs the training venv fine.
#
#   sbatch src/eval/windeval/generators/infinite_diffusion/configs/download_years.sh
#
# Mirrors the 2023 training set exactly (docs/conditional-base-changes.md): hourly, NE-Pacific
# box 55/-135/25/-105 @0.25 deg, ML 49-66, **days 8-14 of every month EXCLUDED** (the v2
# benchmark reference is days 8-14 of 2023; we keep the exclusion in all years so a future
# multi-year eval stays uncontaminated). CDS `reanalysis-era5-complete` allows ~1 active
# request/user -> strictly serial, one explicit-date-list request per month (the shape that
# worked for 2023). OBSERVED (2022 run, Jul 28): 0.5-5 h per month, averaging ~2.3 h and
# trending toward 4-5 h as the MARS queue filled => budget ~2-4 days per year, not one.
# Wall limit is 7 days (partition MaxTime=UNLIMITED); every level is resumable:
# finished year -> zarr exists, skipped; finished month -> grib exists, skipped; killed
# mid-ingest -> partial .building zarr is deleted and rebuilt from the gribs (still on disk).
# Gribs (~8 GB/yr) are deleted after their year's zarr lands (quota headroom).
# Stop the chain with:  touch src/eval/windeval/data/STOP_DL && scancel <jobid>
set -uo pipefail   # NO -e: a transient CDS failure must not kill the loop; we retry.

REPO="/zooper2/${USER}/work/balloon-env-dev"
PY="$REPO/.venv-idiff/bin/python"
DL="$REPO/src/eval/windeval/generators/infinite_diffusion/download_era5_train.py"
DATA="src/eval/windeval/data"
export CDSAPI_RC="/zooper2/${USER}/.cdsapirc"   # $HOME is AFS (unreadable) -> key lives on /zooper2
export PYTHONUNBUFFERED=1
cd "$REPO"

# NOTE (2026-07-29): this trap CANNOT resubmit itself. SLURM client binaries are not
# installed on the compute node at all (`/usr/bin/sbatch` exists only on kahanctrl), so
# the old `sbatch ...` line here died with "command not found" and silently ended the
# chain after 24 h — 20 h of CDS queue time lost. The partition is MaxTime=UNLIMITED, so
# the wall limit is now 7 days (above) and no self-chaining is needed. The safety net is
# a login-node dependency chain instead:
#   J=$(sbatch --parsable .../download_years.sh)
#   sbatch --dependency=afterany:$J .../download_years.sh   # idempotent: re-runs resume
on_term() {
  echo "[$(date '+%F %T')] TERM received (wall limit or scancel). NOT resubmitting:"
  echo "  sbatch does not exist on compute nodes — resubmit from kahanctrl, or rely on"
  echo "  the --dependency=afterany safety-net job. Progress is on disk and resumable."
  exit 143
}
trap on_term TERM

