run_year() {  # $1 = year; dates picked up from DATES_<year>[@]
  local YEAR="$1"
  local ZARR="$DATA/era5_${YEAR}.zarr"
  if [ -d "$ZARR" ]; then
    echo "[$(date '+%F %T')] $YEAR: zarr exists — cleaning stray gribs, skipping"
    rm -f "$DATA/era5_${YEAR}_"*.grib*
    return 0
  fi
  rm -rf "$ZARR.building"    # partial ingest from a killed run — gribs still there, rebuild
  local -n SPECS="DATES_${YEAR}"
  echo "[$(date '+%F %T')] $YEAR: starting (12 monthly requests, hourly, days 8-14 excluded)"
  # Background + wait so the TERM trap (wall-limit resubmit) can fire mid-download.
  "$PY" "$DL" \
    --out "$ZARR.building" --prefix "era5_${YEAR}" --grib-dir "$DATA" \
    --dates "${SPECS[@]}" --time 00/to/23/by/1 --area 55/-135/25/-105 \
    --levels 49 66 --stream &
  wait $! || return 1
  mv "$ZARR.building" "$ZARR"
  rm -f "$DATA/era5_${YEAR}_"*.grib*
  echo "[$(date '+%F %T')] $YEAR: DONE -> $ZARR (gribs deleted)"
}

while :; do
  ALL_DONE=1
  for YEAR in 2022 2021 2020; do
    [ -d "$DATA/era5_${YEAR}.zarr" ] && continue
    ALL_DONE=0
    run_year "$YEAR" || echo "[$(date '+%F %T')] $YEAR: attempt failed — will retry after other years"
  done
  [ "$ALL_DONE" = 1 ] && break
  if [ -f "$DATA/STOP_DL" ]; then echo "[$(date '+%F %T')] STOP_DL — exiting"; exit 1; fi
  echo "[$(date '+%F %T')] pass incomplete — sleeping 10 min before retry"
  sleep 600 &
  wait $!
done
echo "[$(date '+%F %T')] ALL YEARS DONE"
